def build(base=BASE):
 global BASE
 BASE=base.rstrip('/')
 for verification in (ROOT/'verification').glob('google*.html'):
    shutil.copyfile(verification,DIST/verification.name)
 for path,(title,description,body,active) in PAGES.items():
    url=BASE+path
    schema=[{'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':url,'isPartOf':{'@type':'WebSite','name':'Nexa Software','url':BASE+'/'}}]
    if path=='/nexatik/':
      schema.append({'@context':'https://schema.org','@type':'SoftwareApplication','name':'NexaTik','url':url,'description':description,'applicationCategory':'MultimediaApplication','operatingSystem':'Windows 64-bit','softwareVersion':VERSION,'downloadUrl':DOWNLOAD,'screenshot':BASE+'/assets/nexatik-interface.png','offers':{'@type':'Offer','price':'0','priceCurrency':'USD','url':BASE+'/downloads/'}})
    content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{url}"><meta name="theme-color" content="#ee793c"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/assets/nexatik-interface.png"><meta property="og:site_name" content="Nexa Software"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script src="/assets/app.js" defer></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
    destination=DIST/path.strip('/') if path!='/' else DIST
    destination.mkdir(parents=True,exist_ok=True);(destination/'index.html').write_text(content, encoding='utf-8')
 (DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n', encoding='utf-8')
 (DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+path+'</loc></url>' for path in PAGES)+'</urlset>\n', encoding='utf-8')
 (DIST/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Page not found | Nexa Software</title><link rel="stylesheet" href="/assets/style.css"><body><main class="container page-intro"><div class="eyebrow">404 · PAGE NOT FOUND</div><h1>Let’s get you<br>back on track.</h1><p>This page does not exist.</p><a class="button" href="/">Back to Nexa Software →</a></main></body></html>', encoding='utf-8')
 (DIST/'assets/favicon.svg').write_text(LOGO.replace('class="brandmark"','xmlns="http://www.w3.org/2000/svg"'), encoding='utf-8')
if __name__=='__main__':
 import sys
 build(sys.argv[1] if len(sys.argv)>1 else BASE)
